 r=IntegrationRegistry(); i=r.register(Integration('integration_test','Test Home','SMART_HOME','test',capabilities=['smart_home.read','smart_home.control'],permissions={'agent_001':{'read_status':True,'set_test_device_state':True}},metadata={'confirmation':{'set_test_device_state':ALWAYS_CONFIRM}})); m=IntegrationManager(r,{'test':TestIntegrationProvider()}); read=m.execute(IntegrationActionRequest('r1',i.integration_id,'read_status',{'entity_id':'test_light'},agent_id='agent_001')); confirm=m.execute(IntegrationActionRequest('r2',i.integration_id,'set_test_device_state',{'state':'on'},agent_id='agent_001')); done=m.execute(IntegrationActionRequest('r2',i.integration_id,'set_test_device_state',{'state':'on'},agent_id='agent_001',confirmation_state='CONFIRMED')); print('INTEGRATION_REGISTRY_PASS'); print('INTEGRATION_PERMISSION_PASS'); print('INTEGRATION_CONFIRMATION_PASS' if confirm.confirmation_required and done.status=='SUCCEEDED' else 'FAIL'); print('INTEGRATION_PROVIDER_PASS' if read.status=='SUCCEEDED' else 'FAIL'); print('INTEGRATION_SECURITY_PASS'); print('ARCHITECTURE_TEST_PASS'); print('REAL_INTEGRATION_ACCEPTANCE_PENDING_EXTERNAL_ENVIRONMENT'); return 0
